insert into public.book_series(id,name,slug,description) values('10000000-0000-4000-8000-000000000001','4Daniel','4daniel','Historical nonfiction and personal memory. The launch collection includes Book One and Book Two.') on conflict do nothing;
insert into public.books(id,slug,title,subtitle,short_description,full_description,genre,series_id,series_position,cover_path,display_order,tone,themes,source_url,featured,status) values('20000000-0000-4000-8000-000000000001','4daniel-book-one','4Daniel','A Precolonial History and My Life History in Rhodesia and Zimbabwe','An exploration of precolonial Central and Southern Africa, where historical research meets personal memory.',array['The first book in the 4Daniel series brings archaeological evidence and indigenous oral traditions into conversation with Edmund’s own experiences.','It explores the Great Zimbabwe cultural heritage, Swahili trade and Portuguese involvement in the region, tracing a history that reaches beyond colonial accounts. The series began as a legacy for his son Daniel, who grew up in Germany.'],'History & memoir','10000000-0000-4000-8000-000000000001',1,'/images/4daniel-book-one.jpg',1,'sage',array['Precolonial Africa','Cultural heritage','Personal memory'],'https://www.goodreads.com/book/show/210820405-4daniel',false,'published') on conflict do nothing;
insert into public.book_drafts(book_id,data) values('20000000-0000-4000-8000-000000000001','{"slug":"4daniel-book-one","title":"4Daniel","subtitle":"A Precolonial History and My Life History in Rhodesia and Zimbabwe","short_description":"An exploration of precolonial Central and Southern Africa, where historical research meets personal memory.","full_description":["The first book in the 4Daniel series brings archaeological evidence and indigenous oral traditions into conversation with Edmund’s own experiences.","It explores the Great Zimbabwe cultural heritage, Swahili trade and Portuguese involvement in the region, tracing a history that reaches beyond colonial accounts. The series began as a legacy for his son Daniel, who grew up in Germany."],"genre":"History & memoir","series_id":"10000000-0000-4000-8000-000000000001","series_position":1,"cover_asset_id":"","cover_path":"/images/4daniel-book-one.jpg","publication_date":"","language":"en","featured":false,"display_order":1,"tone":"sage","themes":["Precolonial Africa","Cultural heritage","Personal memory"],"source_url":"https://www.goodreads.com/book/show/210820405-4daniel","seo_title":"","seo_description":""}'::jsonb) on conflict do nothing;
