insert into public.books(id,slug,title,subtitle,short_description,full_description,genre,series_id,series_position,cover_path,display_order,tone,themes,source_url,featured,status) values('20000000-0000-4000-8000-000000000002','4daniel-book-two','4Daniel','An African Colonial History and Memoir','The colonial experience of Southern Rhodesia, explored through historical scholarship and lived experience.',array['The second 4Daniel book examines African colonial history, with particular attention to Southern Rhodesia between 1880 and 1980.','Historical analysis is interwoven with memories of growing up in a segregated society and the experiences of early Black students at Peterhouse. Together, these perspectives consider the ways colonial systems shaped education, identity and everyday life.'],'History & memoir','10000000-0000-4000-8000-000000000001',2,'/images/4daniel-book-two.jpg',2,'walnut',array['Colonial history','Education & identity','Lived experience'],'https://www.goodreads.com/book/show/240713691-book-two-4daniel',false,'published') on conflict do nothing;
insert into public.book_drafts(book_id,data) values('20000000-0000-4000-8000-000000000002','{"slug":"4daniel-book-two","title":"4Daniel","subtitle":"An African Colonial History and Memoir","short_description":"The colonial experience of Southern Rhodesia, explored through historical scholarship and lived experience.","full_description":["The second 4Daniel book examines African colonial history, with particular attention to Southern Rhodesia between 1880 and 1980.","Historical analysis is interwoven with memories of growing up in a segregated society and the experiences of early Black students at Peterhouse. Together, these perspectives consider the ways colonial systems shaped education, identity and everyday life."],"genre":"History & memoir","series_id":"10000000-0000-4000-8000-000000000001","series_position":2,"cover_asset_id":"","cover_path":"/images/4daniel-book-two.jpg","publication_date":"","language":"en","featured":false,"display_order":2,"tone":"walnut","themes":["Colonial history","Education & identity","Lived experience"],"source_url":"https://www.goodreads.com/book/show/240713691-book-two-4daniel","seo_title":"","seo_description":""}'::jsonb) on conflict do nothing;
