insert into public.books(id,slug,title,subtitle,short_description,full_description,genre,series_id,series_position,cover_path,display_order,tone,themes,source_url,featured,status) values('20000000-0000-4000-8000-000000000003','the-bile-of-the-river','The Bile of the River','An African Saga','A different way into the past. Edmund’s historical fiction explores African history through the art of storytelling.',array['The Bile of the River brings another literary perspective to Edmund Spencer Katso’s work: historical fiction.','Alongside the research and personal memory of the 4Daniel books, this standalone African saga explores history through fiction.'],'Historical fiction',null,null,'/images/the-bile-of-the-river.jpg',3,'navy',array['Historical fiction','African narratives','Storytelling'],'https://www.goodreads.com/book/show/253569061-an-african-saga',true,'published') on conflict do nothing;
insert into public.book_drafts(book_id,data) values('20000000-0000-4000-8000-000000000003','{"slug":"the-bile-of-the-river","title":"The Bile of the River","subtitle":"An African Saga","short_description":"A different way into the past. Edmund’s historical fiction explores African history through the art of storytelling.","full_description":["The Bile of the River brings another literary perspective to Edmund Spencer Katso’s work: historical fiction.","Alongside the research and personal memory of the 4Daniel books, this standalone African saga explores history through fiction."],"genre":"Historical fiction","series_id":"","series_position":null,"cover_asset_id":"","cover_path":"/images/the-bile-of-the-river.jpg","publication_date":"","language":"en","featured":true,"display_order":3,"tone":"navy","themes":["Historical fiction","African narratives","Storytelling"],"source_url":"https://www.goodreads.com/book/show/253569061-an-african-saga","seo_title":"","seo_description":""}'::jsonb) on conflict do nothing;
