insert into public.pages(slug,title,content,status) values('home','Homepage','{"hero_first":"History","hero_second":"remembered.","hero_italic_first":"Stories","hero_italic_second":"preserved.","hero_description":"Explore the books and life of Edmund Spencer Katso — a personal window into the histories of Central and Southern Africa.","author_standfirst":"From Zimbabwe to Germany, from the classroom to the written page.","author_introduction":"Zimbabwean-born author, educator and historian. Exploring the histories, cultures and lived experiences of Central and Southern Africa.","author_note":"His work brings historical research into conversation with personal memory — preserving a connection between the past and those who will inherit its stories.","featured_book_slug":"the-bile-of-the-river"}'::jsonb,'published') on conflict do nothing;
insert into public.content_drafts(page_slug,title,content) values('home','Homepage','{"hero_first":"History","hero_second":"remembered.","hero_italic_first":"Stories","hero_italic_second":"preserved.","hero_description":"Explore the books and life of Edmund Spencer Katso — a personal window into the histories of Central and Southern Africa.","author_standfirst":"From Zimbabwe to Germany, from the classroom to the written page.","author_introduction":"Zimbabwean-born author, educator and historian. Exploring the histories, cultures and lived experiences of Central and Southern Africa.","author_note":"His work brings historical research into conversation with personal memory — preserving a connection between the past and those who will inherit its stories.","featured_book_slug":"the-bile-of-the-river"}'::jsonb) on conflict do nothing;
insert into public.pages(slug,title,content,status) values('about','Author biography','{"headline_first":"A witness to history.","headline_second":"A keeper of stories.","introduction":"Author. Educator. Historian. A life shaped by Zimbabwe, education and the enduring importance of memory.","chapters":[{"label":"01 / Origins","title":"A life rooted in Zimbabwe.","text":"Born in Umtali, now Mutare, Edmund’s early life and education at St Augustine’s Mission and Peterhouse form part of the personal history behind his writing."},{"label":"02 / Education","title":"Learning. Teaching. Opening doors.","text":"A scholarship took Edmund to the University of Bristol. His career in Zimbabwe included a pioneering teaching role at Peterhouse, connecting a lifetime in education with the experiences that would later inform his books."},{"label":"03 / A wider world","title":"New surroundings. Enduring connections.","text":"After his professional career in Zimbabwe, Edmund relocated to Germany and worked as an English communication trainer. His writing maintains a connection with the country of his birth."},{"label":"04 / The written word","title":"Experience becomes a living archive.","text":"In retirement, Edmund’s literary pursuits bring together history, cultural memory and personal experience. His historical nonfiction and fiction offer different ways to encounter the stories of Central and Southern Africa."}],"milestones":[{"label":"Zimbabwe","title":"Life and work in Zimbabwe","text":"Early life in Umtali, now Mutare, and a professional career that included a pioneering teaching role at Peterhouse."},{"label":"Germany","title":"A new chapter in Germany","text":"Relocated to Germany, where he worked as an English communication trainer and later pursued writing in retirement."}]}'::jsonb,'published') on conflict do nothing;
